CREATE TABLE "User" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "passwordHash" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL);
CREATE TABLE "Baby" ("id" TEXT NOT NULL PRIMARY KEY, "userId" TEXT NOT NULL, "name" TEXT NOT NULL, "birthDate" DATETIME NOT NULL, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" DATETIME NOT NULL, CONSTRAINT "Baby_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "SleepSession" ("id" TEXT NOT NULL PRIMARY KEY, "babyId" TEXT NOT NULL, "startTime" DATETIME NOT NULL, "endTime" DATETIME, "durationMinutes" INTEGER, "notes" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SleepSession_babyId_fkey" FOREIGN KEY ("babyId") REFERENCES "Baby" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "FeedingSession" ("id" TEXT NOT NULL PRIMARY KEY, "babyId" TEXT NOT NULL, "feedingType" TEXT NOT NULL, "amount" REAL, "unit" TEXT, "foodName" TEXT, "startTime" DATETIME NOT NULL, "endTime" DATETIME, "notes" TEXT, "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "FeedingSession_babyId_fkey" FOREIGN KEY ("babyId") REFERENCES "Baby" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "DiaperChange" ("id" TEXT NOT NULL PRIMARY KEY, "babyId" TEXT NOT NULL, "type" TEXT NOT NULL, "timestamp" DATETIME NOT NULL, "notes" TEXT, CONSTRAINT "DiaperChange_babyId_fkey" FOREIGN KEY ("babyId") REFERENCES "Baby" ("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "Expert" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "specialty" TEXT NOT NULL, "credentials" TEXT NOT NULL, "verificationStatus" TEXT NOT NULL, "description" TEXT NOT NULL, "profileImage" TEXT, "contactMethod" TEXT, "availabilityStatus" TEXT NOT NULL, "isDemo" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "ParentQuestion" ("id" TEXT NOT NULL PRIMARY KEY, "userId" TEXT NOT NULL, "babyId" TEXT, "question" TEXT NOT NULL, "category" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'submitted', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ParentQuestion_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "ParentQuestion_babyId_fkey" FOREIGN KEY ("babyId") REFERENCES "Baby" ("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "ConsultationRequest" ("id" TEXT NOT NULL PRIMARY KEY, "userId" TEXT NOT NULL, "expertId" TEXT NOT NULL, "questionId" TEXT, "message" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'pending', "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ConsultationRequest_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User" ("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "ConsultationRequest_expertId_fkey" FOREIGN KEY ("expertId") REFERENCES "Expert" ("id") ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT "ConsultationRequest_questionId_fkey" FOREIGN KEY ("questionId") REFERENCES "ParentQuestion" ("id") ON DELETE SET NULL ON UPDATE CASCADE);
CREATE TABLE "EducationalResource" ("id" TEXT NOT NULL PRIMARY KEY, "title" TEXT NOT NULL, "category" TEXT NOT NULL, "description" TEXT NOT NULL, "sourceName" TEXT NOT NULL, "sourceUrl" TEXT NOT NULL, "reviewedAt" DATETIME);
CREATE TABLE "NutritionProduct" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "brand" TEXT NOT NULL, "category" TEXT NOT NULL, "description" TEXT NOT NULL, "ingredients" TEXT NOT NULL, "ageGuidance" TEXT NOT NULL, "sourceUrl" TEXT NOT NULL, "expertReviewStatus" TEXT NOT NULL DEFAULT 'not_reviewed', "isSample" BOOLEAN NOT NULL DEFAULT true);
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE INDEX "Baby_userId_idx" ON "Baby"("userId");
CREATE INDEX "SleepSession_babyId_startTime_idx" ON "SleepSession"("babyId", "startTime");
CREATE INDEX "SleepSession_babyId_endTime_idx" ON "SleepSession"("babyId", "endTime");
CREATE INDEX "FeedingSession_babyId_startTime_idx" ON "FeedingSession"("babyId", "startTime");
CREATE INDEX "DiaperChange_babyId_timestamp_idx" ON "DiaperChange"("babyId", "timestamp");
CREATE INDEX "Expert_specialty_idx" ON "Expert"("specialty");
CREATE INDEX "ParentQuestion_userId_createdAt_idx" ON "ParentQuestion"("userId", "createdAt");
CREATE INDEX "ParentQuestion_babyId_idx" ON "ParentQuestion"("babyId");
CREATE INDEX "ConsultationRequest_userId_createdAt_idx" ON "ConsultationRequest"("userId", "createdAt");
CREATE INDEX "ConsultationRequest_expertId_idx" ON "ConsultationRequest"("expertId");
CREATE INDEX "EducationalResource_category_idx" ON "EducationalResource"("category");
CREATE INDEX "NutritionProduct_category_idx" ON "NutritionProduct"("category");
CREATE INDEX "NutritionProduct_brand_idx" ON "NutritionProduct"("brand");
CREATE INDEX "NutritionProduct_name_idx" ON "NutritionProduct"("name");
